const COURTESY_MIN_AMOUNT = 100000000;
const COURTESY_WINDOW_DAYS = 3;
const MANAGER_NOTIFY_AMOUNT = 50000000;

function toNum(v) {
  if (v === null || v === undefined || v === '') return 0;
  const n = Number(String(v).split(',').join(''));
  return isNaN(n) ? 0 : n;
}
function dayDiff(fromIso, toIso) {
  const a = Date.parse(String(fromIso) + 'T00:00:00Z');
  const b = Date.parse(String(toIso) + 'T00:00:00Z');
  if (isNaN(a) || isNaN(b)) return null;
  return Math.round((b - a) / 86400000);
}
function stageFor(daysOverdue) {
  if (daysOverdue <= 0) return 'courtesy';
  if (daysOverdue <= 7) return 'reminder';
  if (daysOverdue <= 21) return 'firm';
  if (daysOverdue <= 45) return 'final';
  return 'legal';
}
function bucketFor(daysOverdue) {
  if (daysOverdue <= 0) return 'current';
  if (daysOverdue <= 30) return '1-30';
  if (daysOverdue <= 60) return '31-60';
  if (daysOverdue <= 90) return '61-90';
  return '90+';
}
function harder(stage) {
  const ladder = ['courtesy', 'reminder', 'firm', 'final', 'legal'];
  const i = ladder.indexOf(stage);
  if (i < 0) return stage;
  return ladder[i + 1 < ladder.length ? i + 1 : ladder.length - 1];
}

const today = new Date().toISOString().slice(0, 10);

const custById = {};
for (const it of $('Load Customers').all()) {
  const c = it.json || {};
  if (!c.customer_id) continue;
  custById[String(c.customer_id).trim().toUpperCase()] = c;
}

const out = [];

for (const it of $('Load Open Invoices').all()) {
  const inv = it.json || {};
  const invoiceNumber = String(inv.invoice_number || '').trim();
  const customerId = String(inv.customer_id || '').trim().toUpperCase();
  const dueDate = String(inv.due_date || '').trim();
  const amount = toNum(inv.amount);
  const amountPaid = toNum(inv.amount_paid);
  const outstanding = amount - amountPaid;
  const status = String(inv.status || 'open').trim().toLowerCase();
  const promiseDate = String(inv.promise_date || '').trim();
  const disputeReason = String(inv.dispute_reason || '').trim();
  const cust = custById[customerId] || null;

  const daysOverdue = dayDiff(dueDate, today);

  const problems = [];
  if (!invoiceNumber) problems.push('invoice number is missing');
  if (!customerId) problems.push('customer reference is missing');
  if (!cust) problems.push('customer ' + (customerId || '(blank)') + ' is not in the customer master');
  if (daysOverdue === null) problems.push('due date is missing or unreadable');
  if (!(amount > 0)) problems.push('invoice amount must be greater than zero');
  if (amountPaid < 0) problems.push('amount paid cannot be negative');

  let chaseable = false;
  let stage = '';
  let holdReason = '';
  let outcome = '';
  let brokenPromise = false;

  if (problems.length) {
    outcome = 'data_problem';
    holdReason = 'Not chased: ' + problems.join('; ') + '. A wrong chase costs more goodwill than a late one.';
  } else if (outstanding <= 0) {
    outcome = 'settled';
    holdReason = 'Settled in full on ' + amount + '. Nothing to collect.';
  } else if (status === 'disputed' || disputeReason) {
    outcome = 'disputed';
    holdReason = 'In dispute, so it is never dunned: ' + (disputeReason || 'no reason recorded') + ' Chasing a disputed invoice is how you lose the customer and the argument.';
  } else if (status === 'promised' && promiseDate && dayDiff(today, promiseDate) !== null && dayDiff(today, promiseDate) >= 0) {
    outcome = 'promise_held';
    holdReason = 'Customer promised to pay by ' + promiseDate + ', which has not passed yet. Chasing before the promise date breaks trust for nothing.';
  } else if (status === 'promised') {
    outcome = 'broken_promise';
    brokenPromise = true;
    chaseable = true;
    stage = harder(stageFor(daysOverdue));
    holdReason = '';
  } else if (daysOverdue <= 0) {
    if (outstanding >= COURTESY_MIN_AMOUNT && daysOverdue >= -COURTESY_WINDOW_DAYS) {
      outcome = 'courtesy_due_soon';
      chaseable = true;
      stage = 'courtesy';
    } else {
      outcome = 'not_due';
      holdReason = 'Not due for another ' + (-daysOverdue) + ' days, and under the ' + COURTESY_MIN_AMOUNT + ' courtesy threshold.';
    }
  } else {
    outcome = 'overdue';
    chaseable = true;
    stage = stageFor(daysOverdue);
  }

  out.push({
    json: {
      invoice_number: invoiceNumber,
      customer_id: customerId,
      customer_name: cust ? String(cust.name || '') : '',
      contact_name: cust ? String(cust.contact_name || '') : '',
      contact_email: cust ? String(cust.contact_email || '') : '',
      account_manager: cust ? String(cust.account_manager || '') : '',
      account_manager_slack: cust ? String(cust.account_manager_slack || '') : '',
      credit_limit: cust ? toNum(cust.credit_limit) : 0,
      risk_rating: cust ? String(cust.risk_rating || '') : '',
      payment_terms: cust ? String(cust.payment_terms || '') : '',
      issue_date: String(inv.issue_date || ''),
      due_date: dueDate,
      po_reference: String(inv.po_reference || ''),
      amount: amount,
      amount_paid: amountPaid,
      outstanding: outstanding > 0 ? outstanding : 0,
      currency: String(inv.currency || 'IDR'),
      status: status,
      promise_date: promiseDate,
      dispute_reason: disputeReason,
      days_overdue: daysOverdue === null ? 0 : daysOverdue,
      aging_bucket: daysOverdue === null ? 'unknown' : bucketFor(daysOverdue),
      stage: stage,
      chaseable: chaseable,
      broken_promise: brokenPromise,
      outcome: outcome,
      hold_reason: holdReason,
      notify_manager_threshold: MANAGER_NOTIFY_AMOUNT,
      assessed_on: today,
      execution_id: String($execution.id || 'manual')
    }
  });
}

return out;

const CADENCE_DAYS = { courtesy: 7, reminder: 5, firm: 4, final: 3, legal: 3 };
const LADDER = ['courtesy', 'reminder', 'firm', 'final', 'legal'];

function dayDiff(fromIso, toIso) {
  const a = Date.parse(String(fromIso) + 'T00:00:00Z');
  const b = Date.parse(String(toIso) + 'T00:00:00Z');
  if (isNaN(a) || isNaN(b)) return null;
  return Math.round((b - a) / 86400000);
}
function rank(stage) {
  const i = LADDER.indexOf(stage);
  return i < 0 ? -1 : i;
}

const today = new Date().toISOString().slice(0, 10);

const lastContact = {};
for (const it of $('Load Collection History').all()) {
  const r = it.json || {};
  if (!r.customer_id || !r.sent_on) continue;
  if (String(r.action || '') !== 'chased') continue;
  const k = String(r.customer_id).trim().toUpperCase();
  const prev = lastContact[k];
  if (!prev || String(r.sent_on) > String(prev.sent_on)) lastContact[k] = r;
}

const byCustomer = {};
for (const it of $('Assess Every Invoice').all()) {
  const r = it.json || {};
  const k = String(r.customer_id || '(unknown)').trim().toUpperCase();
  if (!byCustomer[k]) byCustomer[k] = { rows: [], chase: [], held: [] };
  byCustomer[k].rows.push(r);
  if (r.chaseable) byCustomer[k].chase.push(r); else byCustomer[k].held.push(r);
}

const out = [];

for (const k of Object.keys(byCustomer)) {
  const g = byCustomer[k];
  const any = g.rows[0];
  const chase = g.chase;
  const held = g.held;

  const heldNote = held.map(function (r) {
    return r.invoice_number + ' (' + r.outcome + ') ' + r.hold_reason;
  }).join(' | ');

  if (!chase.length) {
    out.push({
      json: {
        customer_id: k,
        customer_name: any.customer_name,
        contact_name: any.contact_name,
        contact_email: any.contact_email,
        account_manager: any.account_manager,
        account_manager_slack: any.account_manager_slack,
        credit_limit: any.credit_limit,
        risk_rating: any.risk_rating,
        next_action: 'hold',
        route: 'hold',
        log_key: k + '|' + today,
        stage: 'none',
        hold_reason: heldNote || 'Nothing outstanding.',
        invoice_numbers: held.map(function (r) { return r.invoice_number; }).join(', '),
        invoice_count: held.length,
        total_outstanding: held.reduce(function (s, r) { return s + (Number(r.outstanding) || 0); }, 0),
        oldest_days_overdue: held.reduce(function (m, r) { return Math.max(m, Number(r.days_overdue) || 0); }, 0),
        broken_promise: false,
        notify_manager: false,
        over_credit_limit: false,
        lines: [],
        last_contacted_on: lastContact[k] ? String(lastContact[k].sent_on) : '',
        assessed_on: today,
        execution_id: String($execution.id || 'manual')
      }
    });
    continue;
  }

  const stage = chase.reduce(function (best, r) {
    return rank(r.stage) > rank(best) ? r.stage : best;
  }, 'courtesy');
  const total = chase.reduce(function (s, r) { return s + (Number(r.outstanding) || 0); }, 0);
  const oldest = chase.reduce(function (m, r) { return Math.max(m, Number(r.days_overdue) || 0); }, 0);
  const broken = chase.some(function (r) { return r.broken_promise; });

  const prev = lastContact[k];
  const sinceLast = prev ? dayDiff(prev.sent_on, today) : null;
  const minGap = CADENCE_DAYS[stage] || 5;
  const suppressed = sinceLast !== null && sinceLast < minGap;

  out.push({
    json: {
      customer_id: k,
      customer_name: any.customer_name,
      contact_name: any.contact_name,
      contact_email: any.contact_email,
      account_manager: any.account_manager,
      account_manager_slack: any.account_manager_slack,
      credit_limit: any.credit_limit,
      risk_rating: any.risk_rating,
      next_action: suppressed ? 'hold' : 'chase',
      route: suppressed ? 'hold' : ((stage === 'final' || stage === 'legal') ? 'escalate' : 'reminder'),
      log_key: k + '|' + today,
      stage: stage,
      hold_reason: suppressed
        ? ('Contacted ' + sinceLast + ' day(s) ago and the ' + stage + ' cadence is one contact every ' + minGap + ' days. Chasing again today would read as harassment.')
        : heldNote,
      invoice_numbers: chase.map(function (r) { return r.invoice_number; }).join(', '),
      invoice_count: chase.length,
      total_outstanding: total,
      oldest_days_overdue: oldest,
      broken_promise: broken,
      notify_manager: !suppressed && (total >= (Number(any.notify_manager_threshold) || 50000000) || stage === 'final' || stage === 'legal'),
      over_credit_limit: total > (Number(any.credit_limit) || 0) && (Number(any.credit_limit) || 0) > 0,
      lines: chase.map(function (r) {
        return {
          invoice: r.invoice_number,
          po: r.po_reference,
          due: r.due_date,
          days_overdue: r.days_overdue,
          outstanding: r.outstanding,
          partly_paid: (Number(r.amount_paid) || 0) > 0,
          broken_promise: r.broken_promise
        };
      }).sort(function (a, b) { return b.days_overdue - a.days_overdue; }),
      held_invoice_numbers: held.map(function (r) { return r.invoice_number; }).join(', '),
      last_contacted_on: prev ? String(prev.sent_on) : '',
      days_since_last_contact: sinceLast === null ? -1 : sinceLast,
      assessed_on: today,
      execution_id: String($execution.id || 'manual')
    }
  });
}

out.sort(function (a, b) { return b.json.total_outstanding - a.json.total_outstanding; });
return out;

